 function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('toasts').appendChild(node);setTimeout(()=>node.remove(),6500);}
 function allow(o=null,adminOnly=false){if(!editable()||(o&&!inScope(o))||(adminOnly&&!admin())){toast(t('accessDenied'),true);return false;}return true;}
 function fail(key){throw new Error(key);}
 function gateProgress(gates){return Math.round(gates.filter(g=>g.status==='completed').reduce((s,g)=>s+Number(g.weight),0)*100)/100;}
 function objectiveProgress(o){if(!o.krs.length)return 0;const total=o.krs.reduce((s,k)=>s+k.weight,0);const value=total?o.krs.reduce((s,k)=>s+k.weight*k.progress,0)/total:o.krs.reduce((s,k)=>s+k.progress,0)/o.krs.length;return Math.min(o.krs.every(k=>k.progress>=100)?100:99.99,Math.round(value*100)/100);}
