 function filtered(){const query=state.query.trim().toLocaleLowerCase();return state.data.objectives.filter(o=>inScope(o)&&(state.team==='all'||o.teamId===state.team)&&(state.owner==='all'||o.ownerId===state.owner||o.krs.some(k=>k.ownerId===state.owner))&&(state.cycle==='all'||txt(o.cycle)===state.cycle)&&(state.status==='all'||objStatus(o)===state.status)&&(state.type==='all'||o.krs.some(k=>k.type===state.type))&&(!query||[txt(o.title),txt(o.description),txt(ownerById(o.ownerId)?.name),...o.krs.map(k=>txt(k.title)+' '+txt(ownerById(k.ownerId)?.name))].join(' ').toLocaleLowerCase().includes(query)));}
 function newGates(start,end){return GATES.map((g,i)=>({id:g.id,weight:g.weight,dueDate:shift(start,Math.round((dateMs(end)-dateMs(start))/DAY*(i+1)/7)),status:'not-started',evidence:{en:'',fa:''},actualDate:null,recordedBy:null,recordedAt:null}));}
 function validateGates(gates,kr){if(!Array.isArray(gates)||gates.length!==7||gates.some((g,i)=>g.id!==GATES[i].id))fail('invalidGate');if(gates.some(g=>!Number.isFinite(g.weight)||g.weight<=0)||Math.abs(gates.reduce((s,g)=>s+g.weight,0)-100)>.001)fail('gateWeights');gates.forEach((g,i)=>{if(!['completed','in-progress','not-started'].includes(g.status))fail('invalidGate');if(!validDate(g.dueDate)||g.dueDate<kr.startDate||g.dueDate>kr.endDate)fail('gateDates');if(i&&g.dueDate<gates[i-1].dueDate)fail('gateDateOrder');if(g.status==='completed'){if(gates.slice(0,i).some(x=>x.status!=='completed'))fail('gateOrder');if(!txt(g.evidence).trim()||!validDate(g.actualDate)||g.actualDate<kr.startDate||g.actualDate>today())fail('gateEvidence');if(i&&g.actualDate<gates[i-1].actualDate)fail('gateDateOrder');}});}
 function validateBase(data){
  const seen=new Set(),id=x=>{if(typeof x!=='string'||!x||seen.has(x))fail('duplicateId');seen.add(x);};
  if(data.version!==6||!Array.isArray(data.objectives)||!Array.isArray(data.owners)||!Array.isArray(data.profiles)||!data.profiles.some(p=>p.role==='admin'))fail('invalidFile');
  if(!Number.isInteger(data.settings.riskDays)||data.settings.riskDays<1||data.settings.riskDays>90)fail('invalidRiskDays');
  data.owners.forEach(o=>{id(o.id);if(!teamById(o.teamId)||!txt(o.name).trim())fail('invalidReference');});
  data.profiles.forEach(p=>{id(p.id);if(p.auth&&!validAuth(p.auth))fail('invalidFile');if(!['admin','editor','viewer'].includes(p.role)||!txt(p.name).trim()||(p.teamId&&!teamById(p.teamId)))fail('invalidReference');});
  const owns=(ownerId,teamId)=>data.owners.some(p=>p.id===ownerId&&p.teamId===teamId);
  data.objectives.forEach(o=>{
   id(o.id);if(!txt(o.title).trim())fail('required');if(!teamById(o.teamId)||!owns(o.ownerId,o.teamId))fail('invalidReference');
   if(!validDate(o.startDate)||!validDate(o.originalEndDate)||!validDate(o.currentEndDate)||o.startDate>o.currentEndDate||o.originalEndDate>o.currentEndDate)fail('invalidDates');
   if(o.actualEndDate&&(!validDate(o.actualEndDate)||o.actualEndDate<o.startDate||o.actualEndDate>today()))fail('actualDateInvalid');
   if(!Array.isArray(o.krs)||!Array.isArray(o.extensions))fail('invalidFile');
   o.krs.forEach(k=>{
    id(k.id);if(!txt(k.title).trim())fail('required');if(!owns(k.ownerId,o.teamId))fail('invalidReference');
    if(!['project','percent'].includes(k.type))fail('invalidFile');
    if(!Number.isFinite(k.weight)||k.weight<0||k.weight>100||!Number.isFinite(k.progress)||k.progress<0||k.progress>100)fail('invalidPercent');
    if(!validDate(k.startDate)||!validDate(k.endDate)||k.startDate<o.startDate||k.endDate>o.currentEndDate||k.startDate>k.endDate)fail('krDates');
    if(k.type==='project'){validateGates(k.gates,k);if(Math.abs(k.progress-gateProgress(k.gates))>.001)fail('invalidGate');if(o.actualEndDate&&k.gates.some(g=>g.actualDate&&g.actualDate>o.actualEndDate))fail('actualDateInvalid');}
   });
   const weights=o.krs.reduce((s,k)=>s+k.weight,0);if(weights>100.001)fail('weightsOver');
   if(o.actualEndDate&&(!o.krs.length||Math.abs(weights-100)>.001||o.krs.some(k=>k.progress<100)))fail('completeRequired');
   o.extensions.forEach(e=>{id(e.id);if(!validDate(e.previousEndDate)||!validDate(e.newEndDate)||e.newEndDate<=e.previousEndDate||e.previousEndDate<o.originalEndDate||e.newEndDate>o.currentEndDate||!txt(e.reason).trim())fail('extendInvalid');});
  });return validateRelations(data);
 }

 function cleanBi(value,max=2000){if(value&&typeof value==='object'&&!Array.isArray(value))return {en:String(value.en||'').slice(0,max),fa:String(value.fa||'').slice(0,max)};return String(value??'').slice(0,max);}
 const LEGACY_DEMOS=new Set(['ارتقای اثربخشی نظام مدیریت عملکرد','تقویت کیفیت برنامه‌های توسعه استعداد','افزایش دقت پیش‌بینی مالی دوره‌ای','کاهش زمان چرخه عملیات مالی','تدوین نقشه ظرفیت شبکه برای دوره آتی','بهبود پایداری سرویس در مناطق اولویت‌دار']);
