  if(old?.type==='project'&&type!=='project'&&old.gates.some(g=>g.status==='completed'))fail('gateTypeLocked');
  const datesChanged=old&&(start!==old.startDate||end!==old.endDate);
  if(datesChanged&&!value('krScheduleReason'))fail('scheduleReasonRequired');
  const k={...(old||{id:uid('kr'),createdAt:new Date().toISOString(),extensions:[]}),title:readBi('krTitle'),ownerId:value('krOwner'),weight:numValue('krWeight'),startDate:start,endDate:end,originalStartDate:old?.originalStartDate||start,originalEndDate:old?.originalEndDate||end,type,progress:type==='percent'?numValue('krProgress'):0,updatedAt:new Date().toISOString()};
