 const toBase64=bytes=>btoa(String.fromCharCode(...new Uint8Array(bytes)));
 const fromBase64=text=>Uint8Array.from(atob(text),c=>c.charCodeAt(0));
 function validAuth(auth){return auth&&auth.algorithm==='PBKDF2-SHA256'&&Number.isInteger(auth.iterations)&&auth.iterations>=100000&&auth.iterations<=600000&&/^[A-Za-z0-9+/]{22}==$/.test(auth.salt)&&/^[A-Za-z0-9+/]{43}=$/.test(auth.hash);}
 async function passwordHash(password,salt,iterations=PASSWORD_ITERATIONS){if(!globalThis.crypto?.subtle)fail('cryptoUnavailable');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return toBase64(await crypto.subtle.deriveBits({name:'PBKDF2',salt:fromBase64(salt),iterations,hash:'SHA-256'},key,256));}
 async function createAuth(password,initial=false){const salt=toBase64(crypto.getRandomValues(new Uint8Array(16)));return {algorithm:'PBKDF2-SHA256',iterations:PASSWORD_ITERATIONS,salt,hash:await passwordHash(password,salt),isInitial:initial,updatedAt:new Date().toISOString()};}
