 function chooseProfile(){state.loginCandidate=state.loginCandidate||state.profileId;const p=state.data.profiles.find(x=>x.id===state.loginCandidate)||profile();modal(t('chooseProfile'),'<div class="switch-grid">'+profilePicker(p.id,'select-switch-profile')+'<section class="switch-password"><h3>'+esc(t('signInAs',{name:p.name}))+'</h3>'+passwordControl('switchPassword',t('password'))+initialPasswordHint(p)+'<p class="small-note">'+esc(t('switchHint'))+'</p></section></div><div class="profile-tools">'+button(t('signOut'),'sign-out','text','logout')+'</div><p class="small-note">'+esc(t('loginNotice'))+'</p>',{kind:'switch-login',data:{id:p.id},submit:'signIn',wide:true});}
 async function signIn(form){const selectedId=form.dataset.id,password=$(form.dataset.kind==='sign-in'?'entryPassword':'switchPassword').value;if(!password)fail('required');const raw=okrStore.getItem(STORAGE);if(String(JSON.parse(raw||'null')?.revision||'')!==state.revision){load();await initializePasswords();}const p=state.data.profiles.find(x=>x.id===selectedId);if(!p||!validAuth(p.auth))fail('wrongPassword');const stamp=authStamp(p),hash=await passwordHash(password,p.auth.salt,p.auth.iterations);if(hash!==p.auth.hash)fail('wrongPassword');if(stamp!==authStamp(state.data.profiles.find(x=>x.id===selectedId)))fail('sessionChanged');state.profileId=selectedId;state.authenticated=true;state.authStamp=stamp;state.undo=[];state.loginCandidate=selectedId;state.view='overview';state.stale=false;resetFilters();state.openTeams.clear();state.openObjectives.clear();state.timelineOpen.clear();state.historyActor='all';$('modal').close();render();}
 function signOut(){state.authenticated=false;state.undo=[];state.loginCandidate=state.profileId;state.openTeams.clear();state.openObjectives.clear();$('modal').close();render();}
 async function initializePasswords(){if(state.loadError)fail('readError');const before=okrStore.getItem(STORAGE),needs=JSON.parse(before||'null')?.version!==6||state.data.profiles.some(p=>!p.auth);if(!needs)return;const next=clone(state.data);await ensurePasswords(next.profiles);if(okrStore.getItem(STORAGE)!==before)fail('conflict');next.version=6;next.revision=uid('rev');next.updatedAt=new Date().toISOString();validate(next);okrStore.setItem(STORAGE,JSON.stringify(next));state.data=next;state.snapshot=clone(next);state.revision=next.revision;}
 async function saveDirectory(form){if(!allow(null,true))return;const kind=form.dataset.kind,isOwner=kind==='owner',list=isOwner?state.data.owners:state.data.profiles,old=list.find(x=>x.id===form.dataset.id),actor=clone(profile()),team=value('entryTeam');if(!value('entryName'))fail('required');if(isOwner&&old&&team!==old.teamId&&ownerUsed(old.id))fail('ownerInUse');const p={id:old?.id||uid(kind),name:readBi('entryName'),teamId:team==='all'?'':team};if(!isOwner){p.role=value('entryRole');if(p.role==='admin')p.teamId='';if(old?.role==='admin'&&p.role!=='admin'&&list.filter(x=>x.role==='admin').length===1)fail('lastAdmin');const password=$('newPassword').value,confirmation=$('confirmPassword').value;if(!old||password||confirmation){if(password.length<4||password.length>160)fail('passwordRequired');if(password!==confirmation)fail('passwordMismatch');p.auth=await createAuth(password);}else p.auth=clone(old.auth);}if(old)list[list.indexOf(old)]=p;else list.push(p);finish(isOwner?'ownerSaved':'profileSaved',{title:p.name},{actor});}
 function dataCore(data){const {audit,revision,updatedAt,...core}=clone(data);return core;}
 function persist(key,args={},options={}){const actor=options.actor||clone(profile());try{if(!state.authenticated||actor.role==='viewer')fail('accessDenied');const disk=JSON.parse(okrStore.getItem(STORAGE)||'null');if(String(disk?.revision||'')!==state.revision)fail('conflict');validate(state.data);const next=clone(state.data),diff=changes(state.snapshot,next),adminOnly=diff.some(c=>['profile','owner','settings','relation'].includes(c.type));if(adminOnly&&actor.role!=='admin')fail('accessDenied');if(actor.role!=='admin'&&actor.teamId&&diff.some(c=>c.teamId&&c.teamId!==actor.teamId))fail('accessDenied');if(diff.length||options.force)next.audit.push({id:uid('event'),at:new Date().toISOString(),actorId:actor.id,actorName:actor.name,key,args,changes:diff});next.revision=uid('rev');next.updatedAt=new Date().toISOString();okrStore.setItem(STORAGE,JSON.stringify(next));if(diff.length&&options.undoable!==false){state.undo.push({before:dataCore(state.snapshot),afterRevision:next.revision,actorId:actor.id,adminOnly,key,args});state.undo=state.undo.slice(-20);}else if(options.undoable!==false&&state.undo.length)state.undo.at(-1).afterRevision=next.revision;state.data=next;state.snapshot=clone(next);state.revision=next.revision;state.fileDirty=true;state.stale=false;state.authStamp=authStamp(profile());toast(t(key,args));return true;}catch(e){state.data=clone(state.snapshot);state.stale=e.message==='conflict';toast(t(STRINGS[e.message]?e.message:'storageError'),true);return false;}}
 function canUndo(){const item=state.undo.at(-1);return !!(state.authenticated&&!state.stale&&editable()&&item&&item.actorId===state.profileId&&item.afterRevision===state.revision&&(!item.adminOnly||admin()));}
 function undoAction(){if(!canUndo()){toast(t('undoUnavailable'),true);return;}const item=state.undo.at(-1),actor=clone(profile()),action={en:STRINGS[item.key]?.[0]?.replace(/\{(\w+)\}/g,(_,k)=>{const v=item.args[k];return v&&typeof v==='object'?v.en||v.fa||'':String(v||'');})||item.key,fa:STRINGS[item.key]?.[1]?.replace(/\{(\w+)\}/g,(_,k)=>{const v=item.args[k];return v&&typeof v==='object'?v.fa||v.en||'':String(v||'');})||item.key};state.data={...clone(item.before),audit:clone(state.data.audit),revision:state.revision,updatedAt:state.data.updatedAt};if(persist('actionUndone',{action},{actor,undoable:false,force:true})){state.undo.pop();if(state.undo.length)state.undo.at(-1).afterRevision=state.revision;render();}}
 async function startWorkspace(){try{load();$('app').innerHTML='<div class="entry-loading" role="status">'+esc(t('initializing'))+'</div>';await initializePasswords();state.authenticated=false;state.loginCandidate=state.profileId;render();}catch(e){$('app').innerHTML='<main class="entry-main"><h1>POLE</h1><p class="notice error">'+esc(t(STRINGS[e.message]?e.message:'storageError'))+'</p></main>';}}

 const relationTypes=['simultaneous','precedent','dependency'];
 const acceptanceTypes=['manual','objective','kr','gateway'];
 function validateRelations(data){
  if(!Array.isArray(data.relations))fail('invalidFile');
  const ids=new Set([...data.profiles.map(p=>p.id),...data.owners.map(o=>o.id),...data.objectives.flatMap(o=>[o.id,...o.krs.flatMap(k=>[k.id,...k.extensions.map(e=>e.id)]),...o.extensions.map(e=>e.id)])]);
  const seen=new Set(),adj=new Map(data.objectives.map(o=>[o.id,[]]));
  for(const r of data.relations){
   if(!r.id||ids.has(r.id)||!relationTypes.includes(r.type))fail('invalidFile');ids.add(r.id);
   if(!adj.has(r.fromId)||!adj.has(r.toId))fail('relationMissing');
   if(r.fromId===r.toId)fail('relationSelf');
   const pair=r.type==='simultaneous'?[r.fromId,r.toId].sort():[r.fromId,r.toId],key=r.type+'|'+pair.join('|');
   if(seen.has(key))fail('relationDuplicate');seen.add(key);
   if(r.type!=='simultaneous')adj.get(r.fromId).push(r.toId);
   if(r.type!=='dependency')continue;
   if(!txt(r.note).trim()||!acceptanceTypes.includes(r.acceptanceRule))fail('requiredOutputError');
   if(r.neededBy&&!validDate(r.neededBy))fail('invalidDates');
   if(!r.needsReview&&(!r.neededBy||!txt(r.acceptanceCriteria).trim()))fail('acceptanceRequired');
   const supplier=findObjective(data,r.fromId),kr=supplier.krs.find(k=>k.id===r.sourceKrId);
   if(['kr','gateway'].includes(r.acceptanceRule)&&!kr)fail('linkedSourceMissing');
   if(r.acceptanceRule==='gateway'&&(kr.type!=='project'||!kr.gates.some(g=>g.id===r.sourceGateId)))fail('linkedSourceMissing');
   if(r.acceptanceRule==='manual'&&r.fulfilled&&!r.legacyReceipt&&(!validDate(r.acceptedDate)||r.acceptedDate>today()||!txt(r.acceptanceEvidence).trim()))fail('receiptEvidenceRequired');
   if(r.acceptedDate&&(!validDate(r.acceptedDate)||r.acceptedDate>today()))fail('actualDateInvalid');
  }
  const visiting=new Set(),done=new Set();
  function visit(id){if(visiting.has(id))fail('relationCycle');if(done.has(id))return;visiting.add(id);for(const next of adj.get(id))visit(next);visiting.delete(id);done.add(id);}
  for(const id of adj.keys())visit(id);
  return data;
 }
 const objectiveDone=o=>!!o&&completionOf(o).done;
 const objectiveName=id=>{const o=getObj(id);return o&&inScope(o)?txt(o.title):t('restrictedObjective');};
 const linksFor=id=>state.data.relations.filter(r=>r.fromId===id||r.toId===id);
 const relationStatus=r=>evaluateRelationship(r);
 const relationBadge=r=>{const e=evaluateRelationship(r);return '<span class="badge '+e.status+'">'+esc(t(e.key,e.args))+'</span>';};
 function acceptanceSourceLabel(r){
  const o=getObj(r.fromId);if(!o||!inScope(o))return t('restrictedObjective');
  if(r.acceptanceRule==='objective')return txt(o.title);
  const k=o.krs.find(k=>k.id===r.sourceKrId);
  return k?txt(k.title)+(r.acceptanceRule==='gateway'?' · '+r.sourceGateId:''):'';
 }
