  return '<article class="relation-card"><div class="relation-route">'+node(first)+'<div class="relation-connector"><span>'+icon(r.type==='simultaneous'?'parallel':dependent?'link':'arrow')+'</span><strong>'+esc(t(r.type))+'</strong></div>'+node(second)+'</div>'+(txt(r.note)?'<p class="relation-note"><strong>'+esc(t(dependent?'requiredOutput':'relationNote'))+'</strong>'+esc(txt(r.note))+'</p>':'')+(dependent?'<div class="relation-acceptance"><dl class="relation-facts"><div><dt>'+esc(t('neededBy'))+'</dt><dd>'+esc(date(r.neededBy))+'</dd></div><div><dt>'+esc(t('acceptanceRule'))+'</dt><dd>'+esc(t('accept_'+r.acceptanceRule))+'</dd></div>'+(e.actualDate?'<div><dt>'+esc(t('receivedDate'))+'</dt><dd>'+esc(date(e.actualDate))+'</dd></div>':'')+'</dl>'+(r.acceptanceRule!=='manual'?'<p>'+esc(acceptanceSourceLabel(r))+'</p>':'')+'<p><strong>'+esc(t('acceptanceCriteria'))+'</strong> '+esc(txt(r.acceptanceCriteria)||t('dependencyNeedsReview'))+'</p>'+(txt(r.acceptanceEvidence)?'<details><summary>'+esc(t('acceptanceEvidence'))+'</summary><p>'+esc(txt(r.acceptanceEvidence))+'</p></details>':'')+(r.legacyReceipt&&!r.acceptedDate?'<p class="small-note">'+esc(t('legacyReceiptHint'))+'</p>':'')+'</div>':r.type==='precedent'?'<p class="relation-note">'+esc(t('precedenceDateRule',{date:date(e.neededBy)}))+'</p>':'')+'<footer class="relation-footer">'+relationBadge(r)+(admin()?button(t('editRelation'),'edit-relation','text','edit',{'data-id':r.id}):'')+'</footer></article>';
