  if(e.status==='overdue')return {tone:'late',label:t(!row.late&&row.k&&e.schedule.sourceType==='gateway'?'gGateLate':!row.late&&!row.k&&e.schedule.status==='overdue'?'gChildLate':!row.late&&e.dependency.top?.state==='overdue'?'gInputLate':'overdue'),symbol:'!'};
  if(['at-risk','blocked','draft'].includes(e.status))return {tone:'risk',label:t(statusKey(e.status)),symbol:'!'};
