  const el=$('ganttScroll'),axis=state.ganttAxis;if(!el||!axis)return;
  const target=axis.todayX+(axis.rtl?0:ganttLabelWidth())-(el.clientWidth-ganttLabelWidth())/2-(axis.rtl?0:ganttLabelWidth());
  el.scrollTo({left:Math.max(0,target),behavior:state.motion?'smooth':'instant'});
