// Image sources belong on <img>, not in inherited CSS variables: the embedded
// gold/aurora data URLs exceed browsers' custom-property size limits.
function setArtwork(image,art,intensity,theme) {
 if(!image)return;
 const selected=Object.hasOwn(ART_ASSETS,art)?art:'none';
 image.hidden=selected==='none';
 if(image.dataset.art!==selected){
  if(selected==='none')image.removeAttribute('src');else image.src=ART_ASSETS[selected];
  image.dataset.art=selected;
 }
 image.style.opacity=String(intensity/100*(theme==='light'?.3:1));
}
function applyAppearance() {
 const root=document.documentElement;
 root.dataset.sidebar=state.sidebarCollapsed?'compact':'full';
 root.dataset.motion=state.motion?'on':'off';
 root.dataset.art=state.art;root.dataset.theme=state.theme;
 root.lang=state.lang;root.dir=state.lang==='fa'?'rtl':'ltr';
 setArtwork($('workspaceArt'),state.art,state.artIntensity,state.theme);
}
