function updateAppearancePreview() {
 const draft=appearanceValues();
 $('appearancePreview').dataset.previewTheme=draft.theme;
 setArtwork($('appearancePreviewArt'),draft.art,draft.artIntensity,draft.theme);
 $('artIntensity').disabled=draft.art==='none';
 $('artIntensityHint').hidden=draft.art!=='none';
 $('artIntensity').nextElementSibling.textContent=pct(draft.artIntensity);
}
function previewAppearanceMotion() {
 const node=$('appearancePreviewDetails'),button=document.querySelector('[data-action="appearance-preview"]');
 const draft=appearanceValues(),card=$('appearancePreviewCard'),before=card.getBoundingClientRect().height;
 node.hidden=!node.hidden;button.setAttribute('aria-expanded',String(!node.hidden));
 if(!draft.motion||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 const after=card.getBoundingClientRect().height;
 card.getAnimations?.().forEach(a=>a.cancel());
 card.animate?.([{height:before+'px'},{height:after+'px'}],{duration:260,easing:'cubic-bezier(.2,0,0,1)'});
 if(!node.hidden)animateSurface(node,draft.motion);
}
function saveAppearance() {
 const draft=appearanceValues();
 if(!Number.isFinite(draft.artIntensity)||draft.artIntensity<10||draft.artIntensity>80)return;
 if(state.lang!==draft.lang)state.cycle='all';
 Object.assign(state,draft);
 preferences();$('modal').close();render();toast(t('appearanceSaved'));
 // render() replaces the toolbar, so restore focus to its new control.
 document.querySelector('.appearance-button')?.focus({preventScroll:true});
}
function animateSurface(node,enabled=state.motion) {
 if(!enabled||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||!node||node.hidden||!node.animate)return;
 node.getAnimations?.().forEach(a=>a.cancel());
 node.animate([{opacity:.35,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'cubic-bezier(.2,0,0,1)'});
}
function animateReveal(id) {animateSurface($(id));}

