function updatePreferenceExamples() {
 if(!$('riskDays'))return;
 $('deadlineRuleExample').textContent=value('riskDays')&&value('riskProgressThreshold')?deadlineRuleExample(numValue('riskDays'),numValue('riskProgressThreshold')):'';
 // Turning a rule off must not leave an invalid, disabled field blocking Save.
 if(!$('linearRisk').checked&&(!value('riskTolerance')||!Number.isFinite(numValue('riskTolerance'))||numValue('riskTolerance')<0||numValue('riskTolerance')>100))$('riskTolerance').value=String(state.data.settings.riskTolerance);
 $('riskTolerance').disabled=!$('linearRisk').checked;
 $('paceRuleExample').textContent=value('riskTolerance')?paceRuleExample($('linearRisk').checked,numValue('riskTolerance')):(!$('linearRisk').checked?t('paceOff'):'');
}
function saveTrackingPreferences() {
 if(!allow(null,true))return;
 const days=numValue('riskDays'),tolerance=numValue('riskTolerance'),threshold=numValue('riskProgressThreshold');
 if(!value('riskDays')||!Number.isInteger(days)||days<1||days>90)fail('invalidRiskDays');
 if(!value('riskTolerance')||!value('riskProgressThreshold')||![tolerance,threshold].every(v=>Number.isFinite(v)&&v>=0&&v<=100))fail('invalidRiskSettings');
 state.data.settings={...state.data.settings,riskDays:days,riskTolerance:tolerance,riskProgressThreshold:threshold,linearRisk:$('linearRisk').checked};
 if(persist('settingsSaved')){render();document.querySelector('.preferences-footer button[type="submit"]')?.focus({preventScroll:true});}
}

