 function mergedData(incoming,mode){if(mode==='replace')return {...incoming,audit:[...new Map([...state.data.audit,...incoming.audit].map(e=>[e.id,e])).values()]};const next=clone(state.data),merge=(base,add)=>{const map=new Map(base.map(x=>[x.id,x]));add.forEach(x=>{if(mode==='update'||!map.has(x.id))map.set(x.id,x);});return [...map.values()];};next.owners=merge(next.owners,incoming.owners);next.profiles=merge(next.profiles,incoming.profiles);next.relations=merge(next.relations||[],incoming.relations||[]);next.objectives=merge(next.objectives,incoming.objectives);next.audit=[...new Map([...next.audit,...incoming.audit].map(e=>[e.id,e])).values()];next.workspaceMode='work';return next;}
 async function applyImport(){if(!allow(null,true)||!state.pending)return;const p=state.pending,mapping=Object.fromEntries(p.unknown.map((id,i)=>[id,value('map'+i)]));if(p.unknown.some(id=>!mapping[id]))fail('mapRequired');const incoming=normalize(p.raw,mapping);incoming.profiles.forEach(entry=>{if(!entry.auth){const old=state.data.profiles.find(x=>x.id===entry.id);if(old?.auth)entry.auth=clone(old.auth);}});await ensurePasswords(incoming.profiles);validate(incoming);if(!allow(null,true))return;const mode=document.querySelector('[name="importMode"]:checked').value,actor=clone(profile()),next=validate(mergedData(incoming,mode));state.data=next;if(finish('dataImported',{title:p.name},{actor,force:true})){if(p.handle){state.fileHandle=p.handle;state.fileText=p.text;state.fileDirty=true;}else if(mode==='replace'){state.fileHandle=null;state.fileText=null;state.fileDirty=false;}state.pending=null;state.openTeams.clear();state.openObjectives.clear();resetFilters();render();}}
